function sb($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>45]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ['ok'=>$http>=200&&$http<300,'data'=>is_array($d)?$d:[],'body'=>$b];}
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$payload=['voice_engine'=>$_POST['voice_engine']??'browser','kokoro_endpoint'=>trim($_POST['kokoro_endpoint']??''),'kokoro_voice'=>trim($_POST['kokoro_voice']??'af_heart'),'browser_voice_name'=>trim($_POST['browser_voice_name']??''),'speaking_rate'=>(float)($_POST['speaking_rate']??1),'speaking_pitch'=>(float)($_POST['speaking_pitch']??1),'updated_at'=>date('c')];$r=sb('PATCH','jessica_voice_settings?setting_name=eq.default',$payload);$msg=$r['ok']?'Voice settings saved.':'Save failed: '.$r['body'];}
